import java.util.*;

public final class NonPokemonBatch88Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("swsh4-5_en_057","swsh4-5_en_065");
    static final List<String> BALLS=List.of("bw1_en_097","sd100_cn_379","bw2_en_093","sd100_cn_373","xy5-5_en_027","xy5-5_en_031","swsh1_en_179","swsh8_en_237","bw5_en_102","swshbsp_en_146");
    static final List<String> WRONG=List.of("me2-5_en_191","xy5_en_133","pokemon-ball");
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static UUID other(UUID p){return NonPokemonBatch67Test.other(p);}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static ServerMatch game(String id,UUID actor){
        var pattern=new ArrayList<>(List.of("basic","basic","basic","basic","basic","energy","trainer","trainer"));pattern.addAll(BALLS);pattern.addAll(WRONG);
        var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();var trainers=new HashMap<String,TrainerProfile>();
        for(String key:new LinkedHashSet<>(pattern)){boolean mon=key.equals("basic")||key.equals("pokemon-ball"),energy=key.equals("energy");var category=mon?TrainerCategory.NONE:key.equals("trainer")||key.equals("xy5_en_133")?TrainerCategory.SUPPORTER:key.equals("me2-5_en_191")?TrainerCategory.TOOL:energy?TrainerCategory.NONE:TrainerCategory.ITEM;
            defs.add(new CardDefinition(key,key,mon?CardCategory.POKEMON:energy?CardCategory.ENERGY:CardCategory.TRAINER,category,"H",Set.of("international"),mon,energy,60,Map.of(),EffectSupport.SUPPORTED,null));
            if(mon)profiles.put(key,new PokemonProfile(500,1,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(300,false)),List.of(),EnergyType.COLORLESS));
            if(!mon&&!energy)trainers.put(key,key.equals("trainer")?NonPokemonBatch2Test.DATA.trainer(id).orElseThrow():NonPokemonBatch2Test.DATA.trainer(key).orElseGet(()->category==TrainerCategory.TOOL?DynamicPassiveModifierTest.plainTool():DeckDiscardTriggeredAbilityTest.trainer(category.name(),"{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":1}")));
        }
        var combat=new CombatCatalog(profiles,Map.of("energy",EnergyType.COLORLESS),trainers,Map.of());var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,pattern.get(i%pattern.size())));decks.add(cards);}
        for(int seed=0;seed<1000;seed++){var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,28);m.drawCardsByEffect(A,B,28);m.endTurn(A);m.endTurn(B);if(actor.equals(B))m.endTurn(A);if(pattern.stream().distinct().allMatch(key->m.privateView(actor).hand().stream().anyMatch(c->c.definitionId().equals(key))))return m;}throw new AssertionError("No Ball Guy fixture");
    }
    static List<CardInstance> stock(ServerMatch m,UUID p,List<String> ids){m.drawCardsByEffect(p,p,m.privateView(p).deck().size());var out=new ArrayList<CardInstance>();for(String id:ids){var card=hand(m,p,id);NonPokemonBatch77Test.top(m,p,card);out.add(card);}return out;}
    static void play(ServerMatch m,UUID p){m.playTrainer(p,hand(m,p,"trainer").instanceId(),null);}
    static ServerMatch aiGame(String id){var m=game(id,A);stock(m,A,List.of("bw1_en_097","sd100_cn_379","bw2_en_093","sd100_cn_373","swsh1_en_179","swsh8_en_237","bw5_en_102","basic","basic","basic","energy","energy","energy"));return m;}
    public static void main(String[] args){selection();duplicates();empty();ai();schema();System.out.println("NonPokemonBatch88Test passed: both printings/owners, 0..3 distinct Item names, cross-language/alternate-print duplicates, faction Great Balls, private search/public reveal/shuffle, stale/wrong choices and all AI difficulties");}
    static void selection(){for(String id:IDS)for(UUID p:List.of(A,B))for(int count:List.of(0,1,2,3)){
        var m=game(id,p);var wanted=List.of("bw2_en_093","xy5-5_en_027","xy5-5_en_031");var ids=new ArrayList<>(wanted);ids.addAll(WRONG);var cards=stock(m,p,ids);int handSize=m.privateView(p).hand().size();var source=hand(m,p,"trainer");play(m,p);var q=m.effectCardPrompt(p);check(q.minimum()==0&&q.maximum()==3&&q.candidates().size()==3&&q.candidates().stream().allMatch(c->wanted.contains(c.definitionId())),"Ball filter offered wrong category/name");check(m.clientView(other(p)).effectSelection()==null&&m.effectCardReveal()==null,"Private Ball search leaked deck");var chosen=cards.subList(0,count);int rng=m.randomTranscript().size();m.submitEffectCards(p,q.resolutionId(),q.step(),chosen.stream().map(CardInstance::instanceId).toList());
        if(count>0){var reveal=m.effectCardReveal();check(reveal!=null&&new HashSet<>(reveal.cardIds()).equals(new HashSet<>(wanted.subList(0,count))),"Selected Ball names not publicly revealed");m.acknowledgeEffectReveal(other(p),reveal.id());}NonPokemonBatch67Test.settle(m);
        check(m.privateView(p).hand().containsAll(chosen)&&m.privateView(p).hand().size()==handSize-1+count&&m.privateView(p).discard().contains(source)&&!m.mayPlaySupporter(p),"Search transfer/Supporter accounting wrong");check(m.randomTranscript().size()-rng==Math.max(0,ids.size()-count-1),"Ball search did not shuffle exactly once after chosen cards removed");GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of()));
    }}
    static void duplicates(){for(UUID p:List.of(A,B))for(List<String> pair:List.of(List.of("bw1_en_097","sd100_cn_379"),List.of("swsh1_en_179","swsh8_en_237"),List.of("bw1_en_097","swshbsp_en_146"))){
        var m=game(IDS.getFirst(),p);var stock=new ArrayList<>(pair);stock.add("bw2_en_093");var cards=stock(m,p,stock);play(m,p);var q=m.effectCardPrompt(p);var before=m.privateView(p);var rng=m.randomTranscript();GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(other(p),q.resolutionId(),q.step(),List.of(cards.getFirst().instanceId())));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),cards.subList(0,2).stream().map(CardInstance::instanceId).toList()));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(hand(m,p,"basic").instanceId())));check(m.privateView(p).equals(before)&&m.randomTranscript().equals(rng)&&m.effectCardReveal()==null,"Invalid name combination leaked/moved/shuffled cards");
        m.toggleEffectCard(p,q.resolutionId(),q.step(),cards.getFirst().instanceId());check(!m.canSelectEffectCard(p,cards.get(1).instanceId())&&m.effectCardPrompt(p).candidates().stream().noneMatch(c->c.equals(cards.get(1))),"UI/AI still offered another printing of selected name");m.toggleEffectCard(p,q.resolutionId(),q.step(),cards.getFirst().instanceId());check(m.canSelectEffectCard(p,cards.get(1).instanceId()),"Deselect did not restore alternate printing");m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(cards.get(1).instanceId(),cards.get(2).instanceId()));NonPokemonBatch67Test.settle(m);check(m.privateView(p).hand().containsAll(cards.subList(1,3)),"Valid different names could not resolve after rejected choice");
    }}
    static void empty(){for(UUID p:List.of(A,B))for(boolean empty:List.of(false,true)){var m=game(IDS.getFirst(),p);stock(m,p,empty?List.of():WRONG);var source=hand(m,p,"trainer");check(m.canPlayTrainer(p,source.instanceId(),null)==!empty,"Hidden filtered deck preflight used contents or allowed empty deck");if(empty)continue;play(m,p);NonPokemonBatch67Test.settle(m);check(m.privateView(p).deck().size()==WRONG.size()&&m.privateView(p).discard().contains(source),"No matching Ball failed to finish/shuffle");}}
    static void ai(){for(var difficulty:AiDifficulty.values()){var m=aiGame(IDS.getFirst());play(m,A);AiCardOperationTest.settle(MatchSession.multiplayer(m,A,B),difficulty);check(!m.hasPendingEffectChoice()&&m.phase()==MatchPhase.TURN,"AI stuck choosing duplicate Ball names: "+difficulty);}}
    static void schema(){String good="{\"type\":\"search_deck\",\"target\":\"DECK\",\"amount\":3,\"minimum\":0,\"card_category\":\"TRAINER\",\"trainer_category\":\"ITEM\",\"reveal\":true,\"distinct_name_groups\":\"one|two;three\"}";for(String bad:List.of(good.replace("one|two;three","one|two;two"),good.replace("one|two;three","one;;three"),good.replace("ITEM","SUPPORTER"),good.replace("\"amount\":3","\"amount\":4"),good.replace("\"reveal\":true","\"reveal\":false")))GeneratedRuleBatch8Test.reject(()->ZoneSelectionEffect.from(EffectRegistry.standard().parse(JsonParser.parseString(bad).getAsJsonObject())));}
}
